package org.springframework.samples.petclinic.model;

/**
 * Derives an owner's preferred contact channel from their own fields:
 * 'EMAIL' when an email is present, otherwise 'PHONE'.
 */
public final class ContactPreference {

    /** Returned when the owner has an email address. */
    public static final String EMAIL = "EMAIL";

    /** Returned when the owner has no email address. */
    public static final String PHONE = "PHONE";

    private ContactPreference() {
    }

    /** 'EMAIL' when the owner has a non-empty email, otherwise 'PHONE'. */
    public static String of(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? EMAIL : PHONE;
    }
}
===== Locality =====
package org.springframework.samples.petclinic.model;

import java.util.Map;

/**
 * Derives an owner's locality (region) from their city using a fixed
 * city-to-region table.
 */
public final class Locality {

    /** City -> canonical region. Anything not listed derives {@link #UNKNOWN}. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Returned when the city is null or not in {@link #CITY_REGION}. */
    public static final String UNKNOWN = "UNKNOWN";

    private Locality() {
    }

    /**
     * The canonical region string for the given city, or {@link #UNKNOWN} when the
     * city is null or not in the fixed city-to-region table.
     */
    public static String of(String city) {
        if (city == null) {
            return UNKNOWN;
        }
        return CITY_REGION.getOrDefault(city, UNKNOWN);
    }
}
===== MembershipLevel =====
package org.springframework.samples.petclinic.model;

/**
 * Derives an owner's numeric membership level, assigned at creation.
 *
 * <p>Starts at 1; add 1 when an email is present; add 1 when {@code namesakeCount}
 * is 0; capped at 3. Level 4 is reserved for tenure.
 */
public final class MembershipLevel {

    /** The maximum level assignable at creation; level 4 is reserved for tenure. */
    public static final int MAX = 3;

    private MembershipLevel() {
    }

    /** The membership level for the given owner. */
    public static int of(Owner owner) {
        int level = 1;
        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
            level++;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            level++;
        }
        return Math.min(level, MAX);
    }
}

